from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
RES=ROOT/'app/src/main/res'; DRAW=RES/'drawable'; VALUES=RES/'values'
(VALUES/'colors.xml').write_text('''<resources><color name="bg">#01192D</color><color name="nav_bg">#02121F</color><color name="surface">#061B2D</color><color name="border">#174662</color><color name="primary">#18A5FF</color><color name="green">#10D977</color><color name="yellow">#FFC53D</color><color name="orange">#FF8A1F</color><color name="red">#FF4055</color><color name="purple">#7452FF</color><color name="text_primary">#F4F7FB</color><color name="text_secondary">#A7B5C8</color><color name="text_muted">#8294AA</color><color name="bist_blue">#18A5FF</color><color name="viop_purple">#7452FF</color><color name="opportunity_orange">#FF8A1F</color><color name="positive_bg">#063C2B</color><color name="negative_bg">#3D1620</color><color name="neutral_bg">#092033</color></resources>\n''',encoding='utf-8')
(DRAW/'bg_surface.xml').write_text('''<shape xmlns:android="http://schemas.android.com/apk/res/android" android:shape="rectangle"><solid android:color="#092033"/><stroke android:width="1dp" android:color="#174662"/><corners android:radius="18dp"/></shape>\n''',encoding='utf-8')
(DRAW/'bg_demo.xml').write_text('''<shape xmlns:android="http://schemas.android.com/apk/res/android" android:shape="rectangle"><solid android:color="#08243A"/><stroke android:width="1dp" android:color="#087ED1"/><corners android:radius="18dp"/></shape>\n''',encoding='utf-8')
def grad(name,a,b,c): (DRAW/name).write_text(f'''<shape xmlns:android="http://schemas.android.com/apk/res/android" android:shape="rectangle"><gradient android:startColor="{a}" android:endColor="{b}" android:angle="0"/><stroke android:width="1dp" android:color="{c}"/><corners android:radius="20dp"/></shape>\n''',encoding='utf-8')
grad('bg_bist.xml','#0B9BFF','#0754C7','#087ED1');grad('bg_opportunity.xml','#08B66B','#017447','#08C878');grad('bg_viop.xml','#594DFF','#2929A7','#7452FF')
layout=RES/'layout/activity_main.xml'; s=layout.read_text(encoding='utf-8')
s=s.replace('android:paddingStart="12dp" android:paddingEnd="12dp" android:paddingTop="8dp" android:paddingBottom="8dp"','android:paddingStart="16dp" android:paddingEnd="16dp" android:paddingTop="10dp" android:paddingBottom="10dp"')
s=s.replace('android:textSize="21sp"','android:textSize="24sp"')
s=s.replace('android:layout_height="64dp" android:orientation="horizontal" android:background="@color/nav_bg"','android:layout_height="76dp" android:orientation="horizontal" android:background="@color/nav_bg"')
s=s.replace('android:id="@+id/marketStatus" android:layout_width="wrap_content" android:layout_height="wrap_content" android:text="● VERİ BEKLENİYOR"','android:id="@+id/marketStatus" android:layout_width="wrap_content" android:layout_height="wrap_content" android:text="● VERİ BEKLENİYOR" android:background="@drawable/bg_demo"')
s=s.replace('android:id="@+id/btnBist" android:layout_width="match_parent" android:layout_height="54dp"','android:id="@+id/btnBist" android:layout_width="match_parent" android:layout_height="54dp"').replace('android:text="BIST TARA   ·   128 Hisse" android:textStyle="bold" android:textColor="@color/bist_blue" android:background="@drawable/bg_surface"','android:text="BIST TARA   ·   Hisseler" android:textStyle="bold" android:textColor="#FFFFFF" android:background="@drawable/bg_bist"')
s=s.replace('android:text="VİOP TARA   ·   Kontratlar" android:textStyle="bold" android:textColor="@color/viop_purple" android:background="@drawable/bg_surface"','android:text="VİOP TARA   ·   Kontratlar" android:textStyle="bold" android:textColor="#FFFFFF" android:background="@drawable/bg_viop"')
s=s.replace('android:text="⚡ FIRSAT KONTROL ET" android:textStyle="bold" android:textColor="@color/opportunity_orange" android:background="@drawable/bg_surface"','android:text="⚡ FIRSAT KONTROL ET" android:textStyle="bold" android:textColor="#FFFFFF" android:background="@drawable/bg_opportunity"')
s=s.replace('android:text="GERÇEK VERİ API AYARLARI"','android:text="AYARLAR"')
s=s.replace('android:text="BIST ve VİOP canlı veri bağlantısı için API bilgilerinizi bu sekmeden girin. Kaynak yapılandırılmadan gecikmeli/demo veri kullanılmaz."','android:text="Uygulama tercihleri ve gerçek veri sağlayıcısı bağlantısı. Canlı kaynak yapılandırılmadan uygulama canlı veri varmış gibi davranmaz."')
